args.sql:
SELECT COUNT(*) FROM households 
WHERE LOWER(TRIM(locregion)) = 'taguatinga'
AND regexp_replace(LOWER(TRIM(socioeconomic->>'Income_Bracket')), E'[\\t ]+', ' ', 'g') IN ('more than r$ 22,000 and less than r$ 26,400', 'more than r$ 26,400');

SELECT COUNT(*) FROM households 
WHERE locregion ILIKE 'taguatinga'
AND LOWER(TRIM(socioeconomic->>'Tenure_Type')) IN ('owned', 'own');

